const savedLang = (typeof localStorage !== 'undefined' && localStorage.getItem('maxshop-courier-lang')) || 'uz';

if (!i18next.isInitialized) {
  i18next.use(initReactI18next).init({
    resources: { uz: { translation: uz }, ru: { translation: ru }, en: { translation: en } },
    lng: savedLang,
    fallbackLng: 'uz',
    interpolation: { escapeValue: false },
    react: { useSuspense: false },
  });
}

i18next.on('languageChanged', (lng) => {
  if (typeof document !== 'undefined') document.documentElement.lang = lng;
  if (typeof localStorage !== 'undefined') localStorage.setItem('maxshop-courier-lang', lng);
});

export default i18next;
